def show(id: Long) = Action { implicit request =>
  val movie = repo.find(id)                              // one model
  render {
    case Accepts.Html() => Ok(views.html.movie(movie))   // Twirl template
    case Accepts.Json() => Ok(Json.toJson(movie))        // Play JSON
  }                                                       // no match => 406
}
